\begin{tikzpicture}[scale=0.85]
\draw[gray!30,very thin,xstep=1,ystep=1] (0,0) grid (8,6);
\draw[->] (0,0)--(0,6.6);
\draw[->] (0,0)--(8.6,0);
\foreach \v/\p in {20/1,40/2,60/3,80/4,100/5,120/6} {\draw (-0.15,\p)--(0,\p); \node[left,font=\scriptsize] at (-0.15,\p) {$\v$};}
\node[below left,font=\scriptsize] at (0,0) {$0$};
\foreach \x in {2,4,6,8} {\node[below,font=\scriptsize] at (\x,0) {$\x$};}
\draw[very thick,blue] (0,6)--(8,2);
\foreach \pt in {(0,6),(8,2)} {\fill[blue] \pt circle (2pt);}
\node[rotate=90,font=\scriptsize] at (-1.3,3) {Mass of soap bar (g)};
