[tikz]
\begin{tikzpicture}[scale=0.5]
\draw[gray!30,very thin,xstep=1,ystep=1] (0,0) grid (12,10);
\draw[->] (0,0)--(0,10.6);
\draw[->] (0,0)--(12.6,0);
\foreach \v/\p in {20/1,40/2,60/3,80/4,100/5,120/6,140/7,160/8,180/9,200/10} {\draw (-0.15,\p)--(0,\p); \node[left,font=\scriptsize] at (-0.15,\p) {$\v$};}
