\draw[->] (0,0)--(0,10.6);
\draw[->] (0,0)--(18.6,0);
\foreach \v/\p in {10/1,20/2,30/3,40/4,50/5,60/6,70/7,80/8,90/9,100/10} {\draw (-0.15,\p)--(0,\p); \node[left,font=\scriptsize] at (-0.15,\p) {$\v$};}
